document.getElementById('sum').textContent=e.length||ra.length?[...ra,...e.map(([k,v])=>(v.sketch?T('sketch {0}',v.sketch):T(PICK[v.pick]))+': '+title(k))].join(' \xB7 '):T('No decisions yet.');
